472→func TestSearchModel_PageNavigation(t *testing.T) {
473→	t.Parallel()
474→
475→	// Create model with 30 results (2 pages)
476→	ss := statusStyles{colorEnabled: false, width: 100}
477→	cfg := search.Config{ServiceURL: "http://test", Owner: "o", Repo: "r"}
478→	results := make([]search.Result, 30)
