100→	})
101→	if err != nil {
102→		t.Fatal(err)
103→	}
104→
105→	if capturedReq.URL.Path != "/search/v1/search" {
106→		t.Errorf("path = %s, want /search/v1/search", capturedReq.URL.Path)
107→	}
108→	if capturedReq.URL.Query().Get("q") != "find bugs" {
